"""PAC Irlanda y Rumanía: reglas, intervenciones y calendario CURADOS a mano. Los importa scripts/build-cap-rules.py.
Cada regla es un resumen propio de Dehesa Index (no el texto legal). Las traducciones (en, fr, it) son de Dehesa Index; vale el texto oficial.
Lo que NO se ha leído (importes por hectárea definitivos, plazos de cada campaña, desarrollo rural) no se inventa: se dice en el texto de cada regla y en data/cap/index.json."""


def W(m, d, y=0): return {'month': m, 'day': d, 'yearOffset': y}
def tr(en, fr, it): return {'en': en, 'fr': fr, 'it': it}


# ============================================================ IRLANDA
# Irlanda no regula estas ayudas en un decreto leído: las condiciones salen de la página del servicio del DAFM, del resumen del plan estratégico y de notas oficiales.
IE_BISS = 'DAFM (gov.ie), Basic Income Support for Sustainability (BISS) Scheme, página del servicio 2026'
IE_BISS_URL = 'https://www.gov.ie/en/service/4ae67-basic-income-support-for-sustainability-biss-scheme/'
