IE_PQ = 'Oireachtas, respuesta del Ministro de Agricultura a una pregunta parlamentaria (22-2-2024)'
IE_PQ_URL = 'https://www.oireachtas.ie/en/debates/question/2024-02-22/84/'
IE_CRISS = 'DAFM (gov.ie), Complementary Redistributive Income Support for Sustainability (CRISS), página del servicio 2023'
IE_CRISS_URL = 'https://www.gov.ie/en/service/b4290-complementary-redistributive-income-support-for-sustainability-criss'
IE_CISYF = 'DAFM (gov.ie), Complementary Income Support for Young Farmers (CISYF), página del servicio 2026'
IE_CISYF_URL = 'https://www.gov.ie/en/service/38d46-complementary-income-support-for-young-farmers'
IE_ECO25 = 'DAFM, nota de prensa sobre los anticipos del Eco-Scheme 2025'
IE_ECO25_URL = 'https://www.gov.ie/en/department-of-agriculture-food-and-the-marine/press-releases/minister-heydon-announces-almost-195-million-in-advance-payments-under-the-2025-eco-scheme-to-almost-110000-farmers'
IE_PR25 = 'DAFM, nota de prensa: 122,151 payment applications submitted by deadline (2025)'
IE_PR25_URL = 'https://www.gov.ie/en/department-of-agriculture-food-and-the-marine/press-releases/minister-heydon-confirms-122151-payment-applications-submitted-by-deadline/'
IE_PR26 = 'DAFM, nota de prensa: 2026 Basic Income Support for Sustainability opens for applications (13-2-2026)'
IE_PR26_URL = 'https://www.gov.ie/ga/an-roinn-talmha%C3%ADochta-bia-agus-mara/preaseisiuinti/2026-basic-income-support-for-sustainability-opens-for-applications'
IE_SI628 = 'S.I. No. 628 of 2023, European Union (CAP Strategic Plan, Information Sharing) Regulations 2023'
IE_SI628_URL = 'https://www.irishstatutebook.ie/eli/2023/si/628/made/en/pdf'
EU_2116 = 'Reglamento (UE) 2021/2116, art. 44'
EU_2116_URL = 'https://gesetze.legal/eu/vo_eu_2021_2116/44'

IE_RULES = [
 ('active-farmer', 'farmer', IE_BISS + '; ' + IE_SUM, [], IE_BISS_URL,
  'Agricultor activo (BISS 2026): quien trabaja o gestiona la tierra que declara; quien no la cultiva ni la gestiona no debe declararla. Cuentan, entre otras cosas, una carga ganadera mínima de 0,10 UGM por hectárea de forraje, producir cultivos, cortar heno o ensilado y mantener elementos del paisaje. El resumen del plan estratégico (noviembre de 2022) preveía exigir un nivel mínimo de actividad y que el solicitante asuma el riesgo económico y agrícola. No se han leído las condiciones (Terms and Conditions) de 2026.', {'minStockingLuPerForageHa': 0.10},
  tr('Active farmer (BISS 2026): the person who farms or manages the land they declare; anyone who neither farms nor manages it should not declare it. Qualifying activities include a minimum stocking rate of 0.10 livestock units per forage hectare, producing crops, cutting hay or silage and maintaining landscape features. The strategic plan summary (November 2022) planned to require a minimum level of activity and that the applicant bears the economic and agricultural risk. The 2026 Terms and Conditions have not been read.',
     "Agriculteur actif (BISS 2026) : celui qui exploite ou gère les terres qu'il déclare ; qui ne les exploite ni ne les gère ne doit pas les déclarer. Comptent notamment une charge minimale de 0,10 UGB par hectare fourrager, produire des cultures, faucher du foin ou de l'ensilage et entretenir des éléments du paysage. Le résumé du plan stratégique (novembre 2022) prévoyait d'exiger un niveau minimal d'activité et que le demandeur supporte le risque économique et agricole. Les conditions (Terms and Conditions) de 2026 n'ont pas été lues.",
     "Agricoltore attivo (BISS 2026): chi coltiva o gestisce la terra che dichiara; chi non la coltiva né la gestisce non deve dichiararla. Contano, tra l'altro, un carico minimo di 0,10 UBA per ettaro foraggero, produrre colture, falciare fieno o insilato e mantenere elementi del paesaggio. Il riassunto del piano strategico (novembre 2022) prevedeva di richiedere un livello minimo di attività e che il richiedente sopporti il rischio economico e agricolo. Le condizioni (Terms and Conditions) del 2026 non sono state lette.")),
 ('eligibility', 'payments', IE_BISS + '; ' + IE_SUM, [], IE_BISS_URL,
  'Acceso al BISS 2026: hace falta una hectárea admisible por cada derecho de pago (una hectárea admisible declarada equivale a un derecho), un número de rebaño registrado o solicitado como muy tarde el 15 de mayo de 2026, y ser agricultor activo. La página oficial no fija una superficie mínima en hectáreas, y el resumen del plan estratégico tampoco la fija para los pagos directos (el mínimo de 3 ha es de otras ayudas, como zonas con limitaciones naturales y agricultura ecológica). No se paga si el importe es inferior a 100 €.', {'eligibleHaPerEntitlement': 1, 'minPaymentEur': 100},
  tr('Access to BISS 2026: one eligible hectare is needed for each payment entitlement (one declared eligible hectare equals one entitlement), a registered herd number or one applied for by 15 May 2026 at the latest, and being an active farmer. The official page sets no minimum area in hectares, and the strategic plan summary sets none for direct payments either (the 3 ha minimum belongs to other schemes, such as areas with natural constraints and organic farming). Nothing is paid if the amount is below €100.',
     "Accès au BISS 2026 : il faut un hectare admissible pour chaque droit au paiement (un hectare admissible déclaré équivaut à un droit), un numéro de troupeau enregistré ou demandé au plus tard le 15 mai 2026, et être agriculteur actif. La page officielle ne fixe pas de superficie minimale en hectares, et le résumé du plan stratégique n'en fixe pas non plus pour les paiements directs (le minimum de 3 ha concerne d'autres aides, comme les zones à contraintes naturelles et l'agriculture biologique). Rien n'est versé si le montant est inférieur à 100 €.",
     "Accesso al BISS 2026: serve un ettaro ammissibile per ogni diritto al pagamento (un ettaro ammissibile dichiarato equivale a un diritto), un numero di mandria registrato o richiesto al più tardi il 15 maggio 2026, ed essere agricoltore attivo. La pagina ufficiale non fissa una superficie minima in ettari e nemmeno il riassunto del piano strategico la fissa per i pagamenti diretti (il minimo di 3 ha riguarda altri aiuti, come le zone con vincoli naturali e l'agricoltura biologica). Non si paga se l'importo è inferiore a 100 €.")),
 ('basic', 'basic', IE_SUM + '; ' + IE_PQ, [], IE_SUM_URL,
  'Apoyo básico a la renta para la sostenibilidad (BISS): se paga por derecho de pago con una hectárea admisible. El valor de cada derecho depende de los derechos y valores de los regímenes anteriores, de la convergencia anual hacia la media nacional entre 2023 y 2026 y de las transferencias. Según el plan estratégico (resumen de noviembre de 2022), los valores convergen hasta un mínimo del 85 % de la media en 2026, con una media nueva estimada de 158,68 € y un valor mínimo de 134,88 €, y un presupuesto de unos 728 millones de euros al año. Son cifras planificadas en 2022: no se han leído los valores reales de los derechos de 2026. Parte del BISS se destina a la reserva nacional para nuevos agricultores y jóvenes.', {'convergenceFloorPct': 85, 'convergenceYears': '2023-2026', 'plannedAverageEur': 158.68, 'plannedMinEntitlementEur': 134.88, 'plannedBudgetEurPerYear': 728000000},
  tr('Basic income support for sustainability (BISS): paid per payment entitlement backed by an eligible hectare. The value of each entitlement depends on the entitlements and values under earlier schemes, annual convergence towards the national average between 2023 and 2026, and transfers. Under the strategic plan (November 2022 summary), values converge to a minimum of 85 % of the average in 2026, with a new estimated average of €158.68 and a minimum value of €134.88, and a budget of about €728 million a year. These are figures planned in 2022: the real 2026 entitlement values have not been read. Part of BISS goes to the national reserve for new and young farmers.',
     "Soutien de base au revenu pour la durabilité (BISS) : versé par droit au paiement adossé à un hectare admissible. La valeur de chaque droit dépend des droits et valeurs des régimes antérieurs, de la convergence annuelle vers la moyenne nationale entre 2023 et 2026 et des transferts. Selon le plan stratégique (résumé de novembre 2022), les valeurs convergent vers un minimum de 85 % de la moyenne en 2026, avec une nouvelle moyenne estimée à 158,68 € et une valeur minimale de 134,88 €, et un budget d'environ 728 millions d'euros par an. Ces chiffres sont ceux planifiés en 2022 : les valeurs réelles des droits de 2026 n'ont pas été lues. Une partie du BISS alimente la réserve nationale pour les nouveaux agriculteurs et les jeunes.",
     "Sostegno di base al reddito per la sostenibilità (BISS): pagato per diritto al pagamento supportato da un ettaro ammissibile. Il valore di ogni diritto dipende dai diritti e dai valori dei regimi precedenti, dalla convergenza annuale verso la media nazionale tra il 2023 e il 2026 e dai trasferimenti. Secondo il piano strategico (riassunto di novembre 2022), i valori convergono verso un minimo dell'85 % della media nel 2026, con una nuova media stimata di 158,68 € e un valore minimo di 134,88 €, e un bilancio di circa 728 milioni di euro l'anno. Sono cifre pianificate nel 2022: i valori reali dei diritti del 2026 non sono stati letti. Una parte del BISS va alla riserva nazionale per nuovi agricoltori e giovani.")),
 ('capping', 'amounts', IE_PQ + '; ' + IE_BISS, [], IE_PQ_URL,
  'Tope de los pagos BISS: según la respuesta del Ministro en el Parlamento (22-2-2024), la parte de 60.000 a 100.000 € se reduce un 85 % y lo que supera 100.000 € se reduce por completo, de modo que el pago máximo efectivo de BISS por agricultor es de 66.000 €. La página oficial de BISS 2026 repite ese máximo efectivo de 66.000 €. La respuesta cita el Reglamento (UE) 2021/2115; no se ha leído el texto del reglamento.', {'reduction60to100kPct': 85, 'reductionOver100kPct': 100, 'effectiveMaxEur': 66000},
  tr('Cap on BISS payments: according to the Minister\'s parliamentary answer (22 February 2024), the part from €60,000 to €100,000 is cut by 85 % and anything above €100,000 is cut entirely, so the effective maximum BISS payment per farmer is €66,000. The official BISS 2026 page repeats that effective maximum of €66,000. The answer cites Regulation (EU) 2021/2115; the text of the regulation has not been read.',
     "Plafonnement des paiements BISS : selon la réponse du ministre au Parlement (22 février 2024), la part de 60 000 à 100 000 € est réduite de 85 % et ce qui dépasse 100 000 € est entièrement supprimé, de sorte que le paiement BISS maximal effectif par agriculteur est de 66 000 €. La page officielle du BISS 2026 reprend ce maximum effectif de 66 000 €. La réponse cite le règlement (UE) 2021/2115 ; le texte du règlement n'a pas été lu.",
     "Tetto ai pagamenti BISS: secondo la risposta del ministro in Parlamento (22 febbraio 2024), la parte da 60.000 a 100.000 € è ridotta dell'85 % e quanto supera 100.000 € è ridotto per intero, per cui il pagamento BISS massimo effettivo per agricoltore è di 66.000 €. La pagina ufficiale del BISS 2026 ripete questo massimo effettivo di 66.000 €. La risposta cita il regolamento (UE) 2021/2115; il testo del regolamento non è stato letto.")),
 ('redistributive', 'redistributive', IE_CRISS + '; ' + IE_SUM, [], IE_CRISS_URL,
  'Apoyo redistributivo complementario (CRISS): se paga por las primeras 30 hectáreas admisibles. Hay que ser agricultor activo, tener al menos un derecho BISS (entero o en parte), tener derecho a cobrar BISS y declarar tierra en Irlanda; no depende del número de derechos. El importe depende de la participación: la ficha de 2023 hablaba de entre unos 40 y 43 €/ha y el resumen del plan (2022) da una media planificada de 43,14 €/ha, con el 10 % del techo de pagos directos (unos 118 millones de euros al año). No se ha leído el importe real de ninguna campaña.', {'firstHa': 30, 'plannedAvgEurPerHa': 43.14, 'allocationPct': 10},
  tr('Complementary redistributive income support (CRISS): paid on the first 30 eligible hectares. The applicant must be an active farmer, hold at least one BISS entitlement (whole or in part), be entitled to BISS and declare land in Ireland; it does not depend on the number of entitlements. The amount depends on take-up: the 2023 page said about €40 to €43/ha and the plan summary (2022) gives a planned average of €43.14/ha, with 10 % of the direct payments ceiling (about €118 million a year). The real amount of any campaign has not been read.',
     "Soutien redistributif complémentaire (CRISS) : versé sur les 30 premiers hectares admissibles. Il faut être agriculteur actif, détenir au moins un droit BISS (entier ou en partie), avoir droit au BISS et déclarer des terres en Irlande ; il ne dépend pas du nombre de droits. Le montant dépend de la participation : la fiche de 2023 parlait d'environ 40 à 43 €/ha et le résumé du plan (2022) donne une moyenne planifiée de 43,14 €/ha, avec 10 % du plafond des paiements directs (environ 118 millions d'euros par an). Le montant réel d'aucune campagne n'a été lu.",
     "Sostegno ridistributivo complementare (CRISS): pagato sui primi 30 ettari ammissibili. Occorre essere agricoltore attivo, detenere almeno un diritto BISS (intero o in parte), avere diritto al BISS e dichiarare terra in Irlanda; non dipende dal numero di diritti. L'importo dipende dalla partecipazione: la scheda del 2023 parlava di circa 40-43 €/ha e il riassunto del piano (2022) indica una media pianificata di 43,14 €/ha, con il 10 % del massimale dei pagamenti diretti (circa 118 milioni di euro l'anno). L'importo reale di nessuna campagna è stato letto.")),
 ('young-farmer', 'young', IE_CISYF + '; ' + IE_SUM, [], IE_CISYF_URL,
  'Apoyo complementario a jóvenes agricultores (CISYF, 2026): tener como máximo 40 años en cualquier momento del año natural de la primera solicitud; haber completado antes del 15 de mayo de 2026 un curso agrario reconocido de nivel 6 del marco nacional de cualificaciones (o equivalente); instalarse por primera vez como jefe de explotación, solo o conjuntamente, o haberlo hecho en los cinco años anteriores a la primera solicitud; tener una solicitud BISS 2026 válida y al menos un derecho. Se paga por hectárea admisible hasta 50 ha y hasta 5 años; la página de 2026 dice que el pago medio será de unos 150 €/ha durante esos 5 años (el resumen del plan de 2022 hablaba de unos 178 €/ha y del 3 % del techo). Una sociedad o grupo puede acceder si el solicitante controla solo o con otros la gestión, los beneficios y el riesgo. No se han leído las condiciones de 2026 en que se basa la página.', {'maxAge': 40, 'maxHa': 50, 'years': 5, 'installedWithinYears': 5, 'nfqLevel': 6, 'averageEurPerHa2026': 150},
  tr('Complementary income support for young farmers (CISYF, 2026): aged 40 or under at any time in the calendar year of the first application; having completed by 15 May 2026 a recognised agricultural course at level 6 of the national framework of qualifications (or equivalent); setting up for the first time as head of the holding, alone or jointly, or having done so in the five years before the first application; having a valid 2026 BISS application and at least one entitlement. Paid per eligible hectare up to 50 ha and for up to 5 years; the 2026 page says the payment will average about €150/ha over those 5 years (the 2022 plan summary spoke of about €178/ha and 3 % of the ceiling). A company or group can qualify if the applicant controls management, benefits and financial risk alone or jointly. The 2026 conditions the page relies on have not been read.',
     "Soutien complémentaire aux jeunes agriculteurs (CISYF, 2026) : avoir 40 ans au plus à un moment quelconque de l'année civile de la première demande ; avoir achevé avant le 15 mai 2026 une formation agricole reconnue de niveau 6 du cadre national des certifications (ou équivalent) ; s'installer pour la première fois comme chef d'exploitation, seul ou conjointement, ou l'avoir fait dans les cinq ans précédant la première demande ; avoir une demande BISS 2026 valide et au moins un droit. Versé par hectare admissible jusqu'à 50 ha et pendant 5 ans au plus ; la page de 2026 indique que le paiement moyen sera d'environ 150 €/ha sur ces 5 ans (le résumé du plan de 2022 parlait d'environ 178 €/ha et de 3 % du plafond). Une société ou un groupe peut y accéder si le demandeur contrôle, seul ou avec d'autres, la gestion, les bénéfices et le risque financier. Les conditions de 2026 sur lesquelles s'appuie la page n'ont pas été lues.",
     "Sostegno complementare ai giovani agricoltori (CISYF, 2026): avere al massimo 40 anni in qualsiasi momento dell'anno civile della prima domanda; aver completato entro il 15 maggio 2026 un corso agrario riconosciuto di livello 6 del quadro nazionale delle qualifiche (o equivalente); insediarsi per la prima volta come capo azienda, da solo o congiuntamente, o averlo fatto nei cinque anni precedenti la prima domanda; avere una domanda BISS 2026 valida e almeno un diritto. Pagato per ettaro ammissibile fino a 50 ha e per un massimo di 5 anni; la pagina del 2026 indica che il pagamento medio sarà di circa 150 €/ha in quei 5 anni (il riassunto del piano del 2022 parlava di circa 178 €/ha e del 3 % del massimale). Una società o un gruppo può accedere se il richiedente controlla, da solo o con altri, la gestione, i benefici e il rischio finanziario. Le condizioni del 2026 su cui si basa la pagina non sono state lette.")),
 ('eco-scheme', 'eco', IE_SUM + '; ' + IE_ECO25, [], IE_SUM_URL,
  'Ecoesquema: voluntario y anual, se elige cada año en la solicitud BISS. El plan estratégico (resumen de 2022) exigía elegir al menos dos de ocho prácticas: espacio para la naturaleza (al menos el 7 % de la explotación), ganadería extensiva (0,10 a 1,4 UGM/ha), limitar el nitrógeno químico, plantar árboles y setos autóctonos, esparcidor o pulverizador con GPS, análisis de suelo y encalado, cultivos de rotación en al menos el 20 % de la superficie arable, y pradera multiespecífica en al menos el 7 % de la superficie admisible. Reserva el 25 % del techo de pagos directos (unos 297 millones de euros al año). Importe: 66 €/ha admisible en 2025 según el DAFM, con un anticipo del 70 % (igual que en 2023 y 2024); el plan preveía unos 77 €/ha indicativos. No se han leído las condiciones de 2026, así que las prácticas pueden haber cambiado.', {'minActions': 2, 'allocationPct': 25, 'plannedEurPerHa': 77, 'rate2025EurPerHa': 66, 'advancePct': 70},
  tr('Eco-scheme: voluntary and annual, chosen each year in the BISS application. The strategic plan (2022 summary) required choosing at least two of eight practices: space for nature (at least 7 % of the holding), extensive livestock (0.10 to 1.4 livestock units/ha), limiting chemical nitrogen, planting native trees and hedges, a GPS-controlled spreader or sprayer, soil sampling and liming, break crops on at least 20 % of the arable area, and a multi-species sward on at least 7 % of the eligible area. It ring-fences 25 % of the direct payments ceiling (about €297 million a year). Amount: €66 per eligible hectare in 2025 according to DAFM, with a 70 % advance (as in 2023 and 2024); the plan indicated about €77/ha. The 2026 conditions have not been read, so the practices may have changed.',
     "Éco-régime : volontaire et annuel, choisi chaque année dans la demande BISS. Le plan stratégique (résumé de 2022) exigeait de choisir au moins deux pratiques parmi huit : espace pour la nature (au moins 7 % de l'exploitation), élevage extensif (0,10 à 1,4 UGB/ha), limitation de l'azote chimique, plantation d'arbres et de haies indigènes, épandeur ou pulvérisateur à guidage GPS, analyse de sol et chaulage, cultures de rupture sur au moins 20 % de la surface arable, et prairie multi-espèces sur au moins 7 % de la surface admissible. Il réserve 25 % du plafond des paiements directs (environ 297 millions d'euros par an). Montant : 66 € par hectare admissible en 2025 selon le DAFM, avec une avance de 70 % (comme en 2023 et 2024) ; le plan indiquait environ 77 €/ha. Les conditions de 2026 n'ont pas été lues, les pratiques ont donc pu changer.",
     "Ecoregime: volontario e annuale, scelto ogni anno nella domanda BISS. Il piano strategico (riassunto del 2022) richiedeva di scegliere almeno due di otto pratiche: spazio per la natura (almeno il 7 % dell'azienda), allevamento estensivo (da 0,10 a 1,4 UBA/ha), limitazione dell'azoto chimico, piantagione di alberi e siepi autoctoni, spandiconcime o irroratrice con GPS, analisi del suolo e calcitazione, colture di rottura su almeno il 20 % della superficie a seminativo e prato polifita su almeno il 7 % della superficie ammissibile. Riserva il 25 % del massimale dei pagamenti diretti (circa 297 milioni di euro l'anno). Importo: 66 € per ettaro ammissibile nel 2025 secondo il DAFM, con un anticipo del 70 % (come nel 2023 e nel 2024); il piano indicava circa 77 €/ha. Le condizioni del 2026 non sono state lette, quindi le pratiche possono essere cambiate.")),
 ('protein-aid', 'associated', IE_SUM, [], IE_SUM_URL,
  'Ayuda asociada a las proteaginosas (protein aid): guisantes, habas, altramuces y soja; la mezcla de proteaginosa y cereal se paga al 50 % de la tasa completa. El plan estratégico (resumen de 2022) preveía una tasa de entre 583 y 350 €/ha, ligada a los cambios en la superficie sembrada, y unos 7 millones de euros al año (unos 35 millones en total). Es lo planificado en 2022: no se ha leído la tasa real de ninguna campaña.', {'plannedEurPerHaMax': 583, 'plannedEurPerHaMin': 350, 'mixSharePct': 50, 'plannedBudgetEurPerYear': 7000000},
  tr('Coupled support for protein crops (protein aid): peas, beans, lupins and soya; a protein/cereal mix is paid at 50 % of the full rate. The strategic plan (2022 summary) planned a rate between €583 and €350/ha, linked to changes in the area grown, and about €7 million a year (about €35 million in total). This is what was planned in 2022: the real rate of any campaign has not been read.',
     "Aide couplée aux protéagineux (protein aid) : pois, féveroles, lupins et soja ; le mélange protéagineux-céréales est payé à 50 % du taux plein. Le plan stratégique (résumé de 2022) prévoyait un taux compris entre 583 et 350 €/ha, lié aux variations de la surface cultivée, et environ 7 millions d'euros par an (environ 35 millions au total). C'est ce qui était planifié en 2022 : le taux réel d'aucune campagne n'a été lu.",
     "Aiuto accoppiato alle colture proteiche (protein aid): piselli, fave, lupini e soia; la miscela proteico-cereale è pagata al 50 % della tariffa piena. Il piano strategico (riassunto del 2022) prevedeva una tariffa tra 583 e 350 €/ha, legata alle variazioni della superficie coltivata, e circa 7 milioni di euro l'anno (circa 35 milioni in totale). È quanto pianificato nel 2022: la tariffa reale di nessuna campagna è stata letta.")),
 ('dates-2026', 'calendar', IE_BISS + '; ' + IE_PR26 + '; ' + IE_PR25, [], IE_BISS_URL,
  'Campaña 2026: la solicitud BISS (con ecoesquema, CRISS y CISYF) y la transferencia de derechos se cierran el 15 de mayo de 2026; las modificaciones sin penalización, el 31 de mayo; las solicitudes tardías, el 9 de junio (con penalización); y la respuesta a los controles preliminares, el 23 de junio según la página oficial (22 de junio según la prensa: no coinciden). En 2025 el cierre fue también el 15 de mayo y las modificaciones sin penalización llegaron hasta el 31 de mayo; en 2023 el cierre fue el 29 de mayo. El DAFM fija estas fechas cada año en sus condiciones: no se han encontrado en una norma como fecha recurrente.', {'campaign': 2026, 'applicationDeadline': '2026-05-15', 'amendmentsDeadline': '2026-05-31', 'lateDeadline': '2026-06-09', 'campaign2025ApplicationDeadline': '2025-05-15', 'campaign2023ApplicationDeadline': '2023-05-29'},
  tr('2026 campaign: the BISS application (with eco-scheme, CRISS and CISYF) and the transfer of entitlements close on 15 May 2026; changes without penalty on 31 May; late applications on 9 June (with a penalty); and the reply to preliminary checks on 23 June according to the official page (22 June according to the press: they differ). In 2025 the closing date was also 15 May and penalty-free changes ran to 31 May; in 2023 it was 29 May. DAFM sets these dates each year in its conditions: they have not been found in a rule as a recurring date.',
     "Campagne 2026 : la demande BISS (avec éco-régime, CRISS et CISYF) et le transfert de droits se clôturent le 15 mai 2026 ; les modifications sans pénalité, le 31 mai ; les demandes tardives, le 9 juin (avec pénalité) ; et la réponse aux contrôles préliminaires, le 23 juin selon la page officielle (22 juin selon la presse : elles diffèrent). En 2025 la clôture était aussi le 15 mai et les modifications sans pénalité allaient jusqu'au 31 mai ; en 2023 la clôture était le 29 mai. Le DAFM fixe ces dates chaque année dans ses conditions : elles n'ont pas été trouvées dans une norme comme date récurrente.",
     "Campagna 2026: la domanda BISS (con ecoregime, CRISS e CISYF) e il trasferimento dei diritti si chiudono il 15 maggio 2026; le modifiche senza penalità il 31 maggio; le domande tardive il 9 giugno (con penalità); e la risposta ai controlli preliminari il 23 giugno secondo la pagina ufficiale (22 giugno secondo la stampa: non coincidono). Nel 2025 la chiusura era pure il 15 maggio e le modifiche senza penalità arrivavano al 31 maggio; nel 2023 la chiusura era il 29 maggio. Il DAFM fissa queste date ogni anno nelle sue condizioni: non sono state trovate in una norma come data ricorrente.")),
 ('late-application', 'penalties', IE_PR25 + '; ' + IE_BISS, [], IE_PR25_URL,
  'Solicitud tardía: se acepta después del cierre (en 2026 hasta el 9 de junio) con una reducción del 1 % por día hábil, según las condiciones citadas por el DAFM en su nota sobre la campaña 2025. No se ha leído el texto de las condiciones de 2026, así que no se sabe si esa regla sigue igual. Incumplir las condiciones del régimen puede suponer una reducción o la pérdida del pago.', {'latePenaltyPerWorkingDayPct': 1, 'lateDeadline2026': '2026-06-09'},
  tr('Late application: accepted after the closing date (in 2026 until 9 June) with a 1 % cut per working day, according to the conditions cited by DAFM in its note on the 2025 campaign. The text of the 2026 conditions has not been read, so it is not known whether that rule is unchanged. Failing to meet the scheme conditions can mean a reduced payment or none.',
     "Demande tardive : acceptée après la clôture (en 2026 jusqu'au 9 juin) avec une réduction de 1 % par jour ouvré, selon les conditions citées par le DAFM dans sa note sur la campagne 2025. Le texte des conditions de 2026 n'a pas été lu, on ne sait donc pas si cette règle est inchangée. Le non-respect des conditions du régime peut entraîner une réduction ou la perte du paiement.",
     "Domanda tardiva: accettata dopo la chiusura (nel 2026 fino al 9 giugno) con una riduzione dell'1 % per giorno lavorativo, secondo le condizioni citate dal DAFM nella sua nota sulla campagna 2025. Il testo delle condizioni del 2026 non è stato letto, quindi non si sa se la regola sia invariata. Il mancato rispetto delle condizioni del regime può comportare una riduzione o la perdita del pagamento.")),
 ('payments', 'calendar', IE_BISS + '; ' + EU_2116, ['44'], IE_BISS_URL,
  'Pagos: la página oficial de BISS 2026 dice que puede haber un anticipo en octubre y que los pagos de saldo empiezan en diciembre. Las fechas de 2026 que da la prensa agraria (Agriland, a partir del calendario del DAFM) son: anticipo BISS desde el 16 de octubre, anticipo del ecoesquema desde el 23 de octubre y saldos desde el 1 de diciembre. La base europea es el art. 44 del Reglamento (UE) 2021/2116: pagos entre el 1 de diciembre y el 30 de junio del año siguiente, con anticipos de hasta el 70 % desde el 16 de octubre; según la copia consolidada leída, para la campaña 2026 se admite un anticipo de hasta el 75 % incluso antes del 16 de octubre. Esa copia es alemana y no oficial: no se ha leído el texto de EUR-Lex.', {'advanceFrom': '10-16', 'paymentFrom': '12-01', 'paymentTo': '06-30', 'advanceMaxPct': 70, 'advanceMaxPct2026': 75},
  tr('Payments: the official BISS 2026 page says an advance may be paid in October and balancing payments start in December. The 2026 dates given by the farm press (Agriland, from the DAFM calendar) are: BISS advance from 16 October, eco-scheme advance from 23 October and balances from 1 December. The EU basis is art. 44 of Regulation (EU) 2021/2116: payments between 1 December and 30 June of the following year, with advances of up to 70 % from 16 October; according to the consolidated copy read, for the 2026 campaign an advance of up to 75 % is allowed even before 16 October. That copy is German and unofficial: the EUR-Lex text has not been read.',
     "Paiements : la page officielle du BISS 2026 indique qu'une avance peut être versée en octobre et que les paiements de solde commencent en décembre. Les dates de 2026 données par la presse agricole (Agriland, d'après le calendrier du DAFM) sont : avance BISS à partir du 16 octobre, avance de l'éco-régime à partir du 23 octobre et soldes à partir du 1er décembre. La base européenne est l'art. 44 du règlement (UE) 2021/2116 : paiements entre le 1er décembre et le 30 juin de l'année suivante, avec des avances jusqu'à 70 % à partir du 16 octobre ; selon la copie consolidée lue, pour la campagne 2026 une avance jusqu'à 75 % est permise même avant le 16 octobre. Cette copie est allemande et non officielle : le texte d'EUR-Lex n'a pas été lu.",
     "Pagamenti: la pagina ufficiale del BISS 2026 indica che può essere pagato un anticipo in ottobre e che i pagamenti di saldo iniziano in dicembre. Le date del 2026 fornite dalla stampa agricola (Agriland, dal calendario del DAFM) sono: anticipo BISS dal 16 ottobre, anticipo dell'ecoregime dal 23 ottobre e saldi dal 1° dicembre. La base europea è l'art. 44 del regolamento (UE) 2021/2116: pagamenti tra il 1° dicembre e il 30 giugno dell'anno successivo, con anticipi fino al 70 % dal 16 ottobre; secondo la copia consolidata letta, per la campagna 2026 è ammesso un anticipo fino al 75 % anche prima del 16 ottobre. Quella copia è tedesca e non ufficiale: il testo di EUR-Lex non è stato letto.")),
 ('data-sharing', 'controls', IE_SI628, ['3', '4'], IE_SI628_URL,
  'Este es el único decreto irlandés leído (S.I. 628/2023, de 12 de diciembre de 2023): solo regula el intercambio de datos de la PAC. Los conjuntos de datos del sistema integrado se comparten gratis entre los organismos competentes y se ponen a disposición del público, salvo que eso perjudique la confidencialidad de datos personales (art. 3). Los datos personales pueden compartirse si el receptor los necesita para sus funciones de la PAC, y quien detecte que son inexactos debe comunicar la corrección (art. 4). No contiene reglas sobre pagos, plazos ni sanciones.', None,
  tr('This is the only Irish statutory instrument read (S.I. 628/2023, of 12 December 2023): it only covers CAP data sharing. Datasets from the integrated system are shared free of charge between the relevant bodies and made publicly available, unless that would harm the confidentiality of personal data (reg. 3). Personal data may be shared if the recipient needs it for its CAP functions, and anyone who finds it inaccurate must report the correction (reg. 4). It contains no rules on payments, deadlines or penalties.',
     "C'est le seul acte réglementaire irlandais lu (S.I. 628/2023, du 12 décembre 2023) : il ne couvre que le partage des données de la PAC. Les jeux de données du système intégré sont partagés gratuitement entre les organismes compétents et rendus publics, sauf si cela nuit à la confidentialité des données personnelles (art. 3). Les données personnelles peuvent être partagées si le destinataire en a besoin pour ses fonctions PAC, et celui qui constate qu'elles sont inexactes doit signaler la correction (art. 4). Il ne contient aucune règle sur les paiements, les délais ou les sanctions.",
     "È l'unico atto regolamentare irlandese letto (S.I. 628/2023, del 12 dicembre 2023): riguarda solo la condivisione dei dati della PAC. I set di dati del sistema integrato sono condivisi gratuitamente tra gli organismi competenti e resi pubblici, salvo che ciò pregiudichi la riservatezza dei dati personali (art. 3). I dati personali possono essere condivisi se il destinatario ne ha bisogno per le sue funzioni PAC, e chi li trova inesatti deve comunicare la correzione (art. 4). Non contiene regole su pagamenti, termini o sanzioni.")),
]
